import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { createWriteStream } from 'node:fs';
import { mkdir, readdir, readFile, unlink } from 'node:fs/promises';
import { join } from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');

// ambientCG publishes Wood 096 (the World's publisher door stands in for ambientCG's own catalog; the twin holds only
// what is published to it)
const twin = process.env.AMBIENTCG_TWIN_URL;
if (!twin) throw new Error('The World names no ambientCG twin URL.');
const published = await fetch(twin + '/_twin/assets', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({"assetId": "Wood096", "dataType": "Material", "displayName": "Wood 096", "tags": ["wood", "knots", "beige"], "creationMethod": "PBRPhotogrammetry", "releaseDate": "2026-08-23 15:00:00", "popularityScore": 2101, "downloadCount": 21, "downloads": [{"attribute": "1K-PNG", "base64": ""}], "thumbnail": "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGNYlaIBAALyATeJSn6HAAAAAElFTkSuQmCC"}) });
assert.equal(published.status, 201, await published.text());

// Volter Editor's ambientCG helpers (volter-ai/editor b86dde8c5618, packages/editor-core/server/asset-library-routes.ts),
// their types removed; its cache is the module's own map
const cache = new Map();
const getCached = (key) => cache.get(key);
const setCache = (key, value) => cache.set(key, value);
function acgTypeParam(type) {
  // ambientCG types: Material, HDRI, etc.
  if (type === 'materials') return 'Material';
  if (type === 'hdris') return 'HDRI';
  return type;
}
async function searchAmbientCG(type, q, offset = 0, limit = 48) {
  const cacheKey = `acg:${type}:${q ?? ''}:${offset}:${limit}`;
  const cached = getCached(cacheKey);
  if (cached) return cached;
  const params = new URLSearchParams({
    type: acgTypeParam(type),
    limit: String(limit),
    offset: String(offset),
    include: 'previewData,downloadData,tagData',
    sort: 'Popular',
  });
  if (q) params.set('q', q);
  const res = await fetch(`https://ambientcg.com/api/v2/full_json?${params}`);
  if (!res.ok) throw new Error(`ambientCG API error: ${res.status}`);
  const data = await res.json();
  const assets = data.foundAssets.map((a) => ({
    id: a.assetId,
    source: 'ambientcg',
    name: a.displayName,
    type: type === 'hdris' ? 'hdri' : 'material',
    thumbnailUrl: a.previewImage?.['256-PNG'] ?? '',
    categories: [],
    tags: a.tags ?? [],
  }));
  // Cache raw data for file extraction later
  for (const a of data.foundAssets) {
    setCache(`acg-raw:${a.assetId}`, a);
  }
  const result = { assets, total: data.numberOfResults };
  setCache(cacheKey, result);
  return result;
}
function getAmbientCGFiles(id) {
  const raw = getCached(`acg-raw:${id}`);
  if (!raw || !raw.downloadFolders) return [];
  const files = [];
  for (const folder of Object.values(raw.downloadFolders)) {
    for (const [_category, cat] of Object.entries(folder.downloadFiletypeCategories)) {
      for (const dl of cat.downloads) {
        const entry = {
          label: dl.attribute || dl.fileName || 'Download',
          format: dl.downloadLink.endsWith('.zip') ? 'zip' : 'unknown',
          url: dl.downloadLink,
        };
        if (dl.fileSizeInBytes != null) entry.sizeBytes = dl.fileSizeInBytes;
        files.push(entry);
      }
    }
  }
  return files;
}
/** Download a single file to a destination path (the import route's downloadFile, its progress reporter left out). */
async function downloadFile(fileUrl, destPath) {
  await mkdir(join(destPath, '..'), { recursive: true });
  const response = await fetch(fileUrl);
  if (!response.ok || !response.body) {
    throw new Error(`Download failed: ${response.status} for ${fileUrl}`);
  }
  await pipeline(Readable.fromWeb(response.body), createWriteStream(destPath));
}

// the artist searches the materials for wood, picks Wood 096 and imports its 1K-PNG zip
const found = await searchAmbientCG('materials', 'wood');
const wood = found.assets.find((asset) => asset.id === 'Wood096');
assert.equal(wood?.name, 'Wood 096');
assert.equal(wood.type, 'material');
assert.deepEqual(wood.tags, ['wood', 'knots', 'beige']);
assert.ok(found.total >= 1);
const thumb = await fetch(wood.thumbnailUrl);
assert.equal(thumb.status, 200, 'the browser shows the preview image the search named');
assert.deepEqual([...new Uint8Array(await thumb.arrayBuffer()).slice(0, 4)], [0x89, 0x50, 0x4e, 0x47]);
// the file list from a fresh server (nothing cached): the same search, the id as the query, one result
cache.clear();
let files = getAmbientCGFiles('Wood096');
if (files.length === 0) {
  await searchAmbientCG('materials', 'Wood096', 0, 1);
  files = getAmbientCGFiles('Wood096');
}
const zip = files.find((file) => file.label === '1K-PNG');
assert.ok(zip, 'the material offers its 1K-PNG download: ' + JSON.stringify(files));
assert.equal(zip.format, 'zip');
const dir = 'asset-library/ambientcg/Wood096';
const filePath = join(dir, 'Wood096.zip');
await downloadFile(zip.url, filePath);
if (zip.sizeBytes != null) assert.equal((await readFile(filePath)).length, zip.sizeBytes);
await new Promise((resolve, reject) => {
  execFile('unzip', ['-o', filePath, '-d', dir], (err) => {
    if (err) reject(err);
    else resolve();
  });
});
await unlink(filePath).catch(() => {});
const extracted = (await readdir(dir)).sort();
assert.deepEqual(extracted, ['Wood096_1K-PNG_Color.png', 'Wood096_1K-PNG_NormalGL.png', 'Wood096_1K-PNG_Roughness.png']);
for (const name of extracted) assert.deepEqual([...(await readFile(join(dir, name))).subarray(0, 4)], [0x89, 0x50, 0x4e, 0x47]);
console.log(JSON.stringify({ imported: dir, extracted }));
